SELECT 
FROM dms_product_pv_config
WHERE tenant_id = #{tenantId} AND id = #{id}

SELECT 
FROM dms_product_pv_config
WHERE tenant_id = #{tenantId}

    AND (product_name LIKE CONCAT('%', #{keyword}, '%') OR sku_name LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}

ORDER BY update_time DESC, id DESC
